# -*- coding: utf-8 -*-
"""RAZ (Recurrent Attentive Zooming) adapter for the crowd-point route.

The vendored implementation lives in ``nets/raz``.  This service adapts it to
the framework's task/checkpoint conventions:

* Main-Net is trained in the paper's sequential stages
  (density -> localization -> attention).
* RAZ-Net is optionally trained on zoom crops generated by Main-Net.
* The final checkpoint contains both ``main`` and ``raz`` state dicts, so a
  single ``raz_best.pth`` can be selected from the normal weight dropdown.
"""
from __future__ import annotations

import base64
import io
import csv
import time
from pathlib import Path
from types import SimpleNamespace
from typing import Dict, Optional, Tuple

import numpy as np
import torch
import torch.nn.functional as F
from PIL import Image, ImageDraw

from nets.raz.datasets import (CrowdDataset, build_dataset_spec,
                               build_datasets, collate_eval, collate_train)
from nets.raz.engine import (evaluate_counts, make_loader, make_optimizer,
                             train_one_epoch)
from nets.raz.models import MainNet, RAZNet, set_trainable
from nets.raz.postprocess import extract_peaks, fuse_density_and_points
from nets.raz.utils import atomic_torch_save, get_device, set_seed
from nets.raz.zoom import generate_zoom_crops, predict_with_zoom

IMAGENET_MEAN = (0.485, 0.456, 0.406)
IMAGENET_STD = (0.229, 0.224, 0.225)


def _make_args(params: dict, save_dir: Path) -> SimpleNamespace:
    """Translate framework parameters to the fields used by nets.raz."""
    epochs = max(1, int(params.get("epochs") or 30))
    raz_epochs = int(params.get("raz_epochs") or 0)
    stage = str(params.get("raz_stage") or "all").lower()
    if stage in ("loc", "localization"):
        stage = "localization"
    elif stage in ("attn", "attention", "proposal"):
        stage = "attention"
    elif stage not in ("all", "density", "raz"):
        stage = "all"
    if stage == "all" and raz_epochs > 0:
        # Explicit RAZ epochs are additional to the Main-Net budget.
        main_total = max(1, epochs)
        d = min(main_total, max(1, main_total // 3))
        rem = main_total - d
        loc = min(rem, max(1, rem // 2)) if rem else 0
        attn = max(0, rem - loc)
        r = raz_epochs
    elif stage == "all":
        # Honor the user's total epoch budget exactly.  With a tiny budget
        # (e.g. 1) only the earliest stages run; RAZ is skipped and the UI
        # shows 1/1 instead of an unexpected 3/3.
        d = min(epochs, max(1, epochs // 4))
        rem = epochs - d
        loc = min(rem, max(1, rem // 3)) if rem else 0
        rem -= loc
        attn = min(rem, max(1, rem // 2)) if rem else 0
        r = max(0, rem - attn)
    elif stage == "density":
        d, loc, attn, r = epochs, 0, 0, 0
    elif stage == "localization":
        d, loc, attn, r = 0, epochs, 0, 0
    elif stage == "attention":
        d, loc, attn, r = 0, 0, epochs, 0
    else:  # raz
        d, loc, attn, r = 0, 0, 0, epochs
    opt = str(params.get("optimizer") or "adamw").lower()
    if opt not in ("sgd", "adam", "adamw"):
        opt = "adam"
    return SimpleNamespace(
        data_root=str(params["dataset_path"]),
        dataset=str(params.get("raz_dataset") or "auto"),
        part=params.get("part") or None,
        val_ratio=float(params.get("val_ratio", 0.2) or 0.2),
        seed=int(params.get("seed", 42) or 42),
        manifest=str(params.get("manifest") or ""),
        train_sub=str(params.get("train_sub") or ""),
        test_sub=str(params.get("test_sub") or ""),
        max_train=int(params.get("max_train") or 0),
        max_val=int(params.get("max_val") or 0),
        allow_density_gt=bool(params.get("allow_density_gt", True)),
        density_threshold=float(params.get("density_threshold", 0.05) or 0.05),
        patch_size=max(32, int(params.get("img_size") or 256)),
        max_side=max(0, int(params.get("max_side") or 1536)),
        attn_stride=4,
        beta=0.1,
        sigma_z=3.0,
        no_augment=not bool(params.get("augment", True)),
        pretrained=bool(params.get("pretrained", True)),
        vgg_weights=str(params.get("vgg_weights") or ""),
        device=str(params.get("device") or "cpu"),
        batch_size=max(1, int(params.get("batch_size") or 2)),
        num_workers=max(0, int(params.get("num_workers") or 0)),
        lr=float(params.get("lr") or 1e-4),
        weight_decay=float(params.get("weight_decay") or 1e-5),
        momentum=float(params.get("momentum") or 0.95),
        optimizer=opt,
        patience=4,
        output_dir=str(save_dir),
        log_every=0,
        gamma=float(params.get("gamma") or 100.0),
        attn_pos_weight=float(params.get("attn_pos_weight") or 1.0),
        peak_threshold=float(params.get("peak_threshold") or 0.3),
        fusion_threshold=float(params.get("fusion_threshold") or 5.0),
        epochs=epochs,
        raz_epochs=raz_epochs,
        stage=stage,
        # Parsed stage budget (not a standard argparse field).
        _stage_epochs=(d, loc, attn, r),
    )


def _set_stage_trainable(model: MainNet, stage: str) -> None:
    stage = stage.lower()
    if stage == "density":
        set_trainable(model.backbone, True)
        set_trainable(model.count_trunk, True)
        set_trainable(model.count_out, True)
        set_trainable(model.loc_head, False)
        set_trainable(model.attn_head, False)
    elif stage in ("localization", "loc"):
        set_trainable(model.backbone, True)
        set_trainable(model.count_trunk, False)
        set_trainable(model.count_out, False)
        set_trainable(model.loc_head, True)
        set_trainable(model.attn_head, False)
    elif stage in ("attention", "attn", "proposal"):
        set_trainable(model.backbone, True)
        set_trainable(model.count_trunk, False)
        set_trainable(model.count_out, False)
        set_trainable(model.loc_head, False)
        set_trainable(model.attn_head, True)
    elif stage == "raz":
        set_trainable(model, True)
    else:
        raise ValueError(f"unknown RAZ stage: {stage}")


def _snapshot(model: torch.nn.Module) -> Dict[str, torch.Tensor]:
    return {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}


def _checkpoint(main: MainNet, raz: Optional[RAZNet], args,
                stage: str, epoch: int, best: Optional[float]) -> dict:
    return {
        "model": main.state_dict(),
        "main": main.state_dict(),
        "raz": raz.state_dict() if raz is not None else None,
        "meta": {
            "model": "raz", "route": "crowd_point", "task": "crowd_point",
            "stage": stage, "raz": raz is not None,
            "img_size": int(args.patch_size),
            "patch_size": int(args.patch_size),
            "attn_stride": int(args.attn_stride),
            "beta": float(args.beta), "sigma_z": float(args.sigma_z),
        },
        "epoch": int(epoch), "best": best,
    }


def _save(path: Path, main: MainNet, raz: Optional[RAZNet], args,
          stage: str, epoch: int, best: Optional[float]) -> None:
    atomic_torch_save(_checkpoint(main, raz, args, stage, epoch, best), path)


def _run_stage(task, model, main_model: Optional[MainNet],
               train_loader, val_loader, args, stage: str, epochs: int,
               state: dict, best_path: Path, last_path: Path,
               csv_path: Path, aux_loss=None,
               aux_w: float = 1.0) -> Optional[float]:
    if epochs <= 0:
        return None
    _set_stage_trainable(model, stage)
    optimizer = make_optimizer(model, args)
    scheduler = torch.optim.lr_scheduler.ReduceLROnPlateau(
        optimizer, mode="min", factor=0.5, patience=args.patience)
    best = float("inf")
    best_state = None
    for local_epoch in range(1, epochs + 1):
        if task.stop_event.is_set():
            raise StopIteration()
        loss = train_one_epoch(model, train_loader, optimizer, args.device,
                               stage, args, local_epoch,
                               aux_loss=aux_loss, aux_w=aux_w)
        metrics = evaluate_counts(
            model, val_loader, args.device,
            peak_threshold=args.peak_threshold,
            fusion_threshold=args.fusion_threshold,
            has_density=(stage != "raz"))
        score = (metrics["density"]["mae"] if stage == "density"
                 else metrics["loc"]["mae"])
        scheduler.step(score)
        state["done"] += 1
        state["epoch"] = state["done"]
        task.epoch = state["done"]
        task.total_epochs = state["total"]
        task.progress = state["done"] / max(1, state["total"]) * 100.0
        task.metrics = {
            "train_loss": round(float(loss), 5),
            "val_mae": round(float(score), 4),
            "val_rmse": round(float(metrics["loc" if stage != "density"
                                             else "density"]["rmse"]), 4),
        }
        task.history.append({"epoch": state["done"], **task.metrics})
        with open(csv_path, "a", newline="", encoding="utf-8") as f:
            csv.writer(f).writerow([
                state["done"], f"{loss:.5f}", "", task.metrics["val_mae"],
                task.metrics["val_rmse"]])
        task.log(f"[{stage}] epoch {local_epoch}/{epochs} "
                 f"(global {state['done']}/{state['total']}) | "
                 f"loss {loss:.4f} | val MAE {score:.3f} | "
                 f"loc MAE {metrics['loc']['mae']:.3f} | "
                 f"fused MAE {metrics['fused']['mae']:.3f}")
        current_main = main_model if main_model is not None else model
        current_raz = model if stage == "raz" else None
        _save(last_path, current_main, current_raz, args, stage,
              state["done"], task.best or None)
        if score < best:
            best = float(score)
            best_state = _snapshot(model)
            task.best = {"epoch": state["done"], "val_mae": round(score, 4)}
            _save(best_path, current_main, current_raz, args, stage,
                  state["done"], task.best)
    if best_state is not None:
        model.load_state_dict(best_state)
    return None if best == float("inf") else best


def run_raz_train(task, params: dict):
    """Framework training entry for RAZ on the crowd-point route."""
    from app.services.crowd_counting import clear_inference_cache
    from app.services.train_common import save_loss_curves

    device = get_device(str(params.get("device") or "cpu"))
    params = dict(params)
    params["device"] = str(device)
    set_seed(int(params.get("seed", 42) or 42))
    save_dir = Path(task.save_dir)
    save_dir.mkdir(parents=True, exist_ok=True)
    args = _make_args(params, save_dir)
    d_epochs, loc_epochs, attn_epochs, raz_epochs = args._stage_epochs
    total = d_epochs + loc_epochs + attn_epochs + raz_epochs
    if total <= 0:
        raise ValueError("RAZ 训练轮数必须大于 0")
    task.total_epochs = total
    task.log(f"RAZ 训练 | stage={args.stage} | Main-Net stages: "
             f"density={d_epochs}, localization={loc_epochs}, "
             f"attention={attn_epochs}"
             + (f", RAZ={raz_epochs}" if raz_epochs else "")
             + f" | 总 epoch={total}")
    task.log(f"数据: {args.data_root} | patch={args.patch_size} | "
             f"batch={args.batch_size} | device={args.device}")
    loss_name = str(params.get("loss") or "raz")
    aux_loss, aux_w = None, 1.0
    if loss_name.startswith("custom:"):
        from app.core.registry import get_custom_loss, is_custom_loss_for
        if not is_custom_loss_for(loss_name, "crowd_point"):
            raise ValueError(f"自定义损失 {loss_name} 未注册到 crowd_point 路线")
        aux_loss = get_custom_loss(loss_name, task="crowd_point")
        if hasattr(aux_loss, "to"):
            aux_loss = aux_loss.to(device)
        lw = params.get("loss_weights") or {}
        aux_w = float(lw.get("aux_w", params.get("loss_weight", 1.0)) or 1.0)
        task.log(f"自定义附加损失: {loss_name}（权重 {aux_w}）")
    else:
        task.log(f"损失: RAZ 内置 stage loss（{loss_name or 'raz'}）")
    if args.stage == "raz" and not params.get("weight_path"):
        raise ValueError("RAZ 单阶段训练需要 Main-Net 初始化权重"
                         "（请选择训练产物或上传权重）")
    clear_inference_cache()

    spec, train_ds, val_ds, _test_ds = build_datasets(args)
    task.log(f"数据划分: {spec.summary()} | {spec.name}")
    train_loader = make_loader(train_ds, args, train=True)
    val_loader = make_loader(val_ds, args, train=False)

    main = MainNet(pretrained=args.pretrained,
                   weights_path=args.vgg_weights or None)
    if params.get("weight_path"):
        _load_main_weights(main, params["weight_path"])
    main.to(device)
    task.log(f"Main-Net 参数量: {sum(p.numel() for p in main.parameters()) / 1e6:.2f}M")

    best_path = save_dir / "raz_best.pth"
    last_path = save_dir / "raz_last.pth"
    csv_path = save_dir / "metrics.csv"
    with open(csv_path, "w", newline="", encoding="utf-8") as f:
        csv.writer(f).writerow(["epoch", "train_loss", "val_loss",
                                "val_mae", "val_rmse"])
    state = {"done": 0, "total": total, "epoch": 0}
    task.best = {}

    _run_stage(task, main, None, train_loader, val_loader, args,
               "density", d_epochs, state, best_path, last_path, csv_path,
               aux_loss=aux_loss, aux_w=aux_w)
    _run_stage(task, main, None, train_loader, val_loader, args,
               "localization", loc_epochs, state, best_path, last_path,
               csv_path, aux_loss=aux_loss, aux_w=aux_w)
    _run_stage(task, main, None, train_loader, val_loader, args,
               "attention", attn_epochs, state, best_path, last_path,
               csv_path, aux_loss=aux_loss, aux_w=aux_w)

    raz = None
    if raz_epochs > 0:
        if task.stop_event.is_set():
            raise StopIteration()
        task.log("生成 RAZ 训练用 zoom crops（由 Main-Net 注意力选择局部区域）")
        cache = save_dir / "zoom_cache"
        generate_zoom_crops(
            model=main, items=spec.train, out_dir=cache, device=device,
            max_side=args.max_side, theta_z=0.01, kz=10, scale=2.0,
            seed=args.seed, allow_density_gt=args.allow_density_gt,
            density_threshold=args.density_threshold, log=task.log)
        zspec = build_dataset_spec(cache, dataset="custom",
                                   val_ratio=args.val_ratio, seed=args.seed)
        if not zspec.train:
            task.log("未生成有效 zoom crops，跳过 RAZ-Net 训练，仅保留 Main-Net")
        else:
            common = dict(patch_size=args.patch_size, max_side=args.max_side,
                          attn_stride=args.attn_stride, beta=args.beta,
                          sigma_z=args.sigma_z,
                          allow_density_gt=args.allow_density_gt,
                          density_threshold=args.density_threshold)
            ztrain = CrowdDataset(zspec.train, train=True,
                                  augment=not args.no_augment, **common)
            zval = CrowdDataset(zspec.val or zspec.train, train=False,
                                augment=False, **common)
            ztrain_loader = make_loader(ztrain, args, train=True)
            zval_loader = make_loader(zval, args, train=False)
            raz = RAZNet(pretrained=False)
            raz.load_from_main(main)
            raz.to(device)
            task.log(f"RAZ-Net: train={len(ztrain)} | val={len(zval)}")
            _run_stage(task, raz, main, ztrain_loader, zval_loader, args,
                       "raz", raz_epochs, state, best_path, last_path,
                       csv_path, aux_loss=aux_loss, aux_w=aux_w)

    if not best_path.exists():
        _save(best_path, main, raz, args, "final", state["done"], task.best)
    _save(last_path, main, raz, args, "final", state["done"], task.best)
    try:
        save_loss_curves(save_dir, task.history, ("val_mae", "val_rmse"))
    except Exception:
        pass
    task.progress = 100.0
    task.result = {"best_weight": str(best_path), "last_weight": str(last_path),
                   "best_val_mae": task.best.get("val_mae"),
                   "save_dir": str(save_dir), "model": "raz",
                   "has_raz": bool(raz is not None)}
    task.log(f"RAZ 训练完成 | best={task.best.get('val_mae')} | "
             f"权重: {best_path}")


def _load_main_weights(model: MainNet, weight_path: str) -> None:
    ck = torch.load(str(weight_path), map_location="cpu", weights_only=False)
    sd = None
    if isinstance(ck, dict):
        sd = ck.get("main") or ck.get("model_state_dict") or ck.get("state_dict")
        if sd is None and isinstance(ck.get("model"), dict):
            sd = ck["model"]
    if not isinstance(sd, dict):
        sd = ck if isinstance(ck, dict) else None
    if not isinstance(sd, dict):
        raise ValueError(f"RAZ 权重文件无效: {weight_path}")
    sd = {k[7:] if k.startswith("module.") else k: v for k, v in sd.items()}
    model.load_state_dict(sd, strict=False)


def _load_raz_bundle(weight_path: str) -> Tuple[MainNet, Optional[RAZNet],
                                               dict]:
    ck = torch.load(str(weight_path), map_location="cpu",
                    weights_only=False)
    if not isinstance(ck, dict):
        raise ValueError(f"RAZ 权重文件无效: {weight_path}")
    main_sd = ck.get("main") or ck.get("model_state_dict") or ck.get("state_dict")
    if main_sd is None and isinstance(ck.get("model"), dict):
        main_sd = ck["model"]
    if not isinstance(main_sd, dict):
        raise ValueError(f"RAZ 权重中未找到 Main-Net 参数: {weight_path}")
    main_sd = {k[7:] if k.startswith("module.") else k: v
               for k, v in main_sd.items()}
    main = MainNet(pretrained=False)
    main.load_state_dict(main_sd, strict=False)
    raz = None
    raz_sd = ck.get("raz")
    if isinstance(raz_sd, dict):
        raz = RAZNet(pretrained=False)
        raz.load_from_main(main)
        raz_sd = {k[7:] if k.startswith("module.") else k: v
                  for k, v in raz_sd.items()}
        raz.load_state_dict(raz_sd, strict=False)
    return main, raz, (ck.get("meta") or {})


def _to_b64(img: Image.Image) -> str:
    buf = io.BytesIO()
    img.save(buf, format="PNG")
    return base64.b64encode(buf.getvalue()).decode()


def raz_infer(image: Image.Image, weight_path=None, device="cpu",
              pretrained=False, conf_threshold=0.5, max_side=1536,
              raz_rounds=1):
    """Single-image RAZ inference used by the framework's inference route."""
    if not weight_path:
        raise ValueError("RAZ 推理需要训练产物权重（raz_best.pth / raz_last.pth）")
    if device.startswith("cuda") and not torch.cuda.is_available():
        device = "cpu"
    dev = torch.device(device)
    from app.services.crowd_counting import (_model_cache_get,
                                             _model_cache_put,
                                             _model_cache_key)
    key = _model_cache_key("raz", weight_path, device)
    cached = _model_cache_get(key)
    if cached is None:
        main, raz, meta = _load_raz_bundle(str(weight_path))
        main.to(dev).eval()
        if raz is not None:
            raz.to(dev).eval()
        cached = (main, raz, meta)
        _model_cache_put(key, cached)
    main, raz, _meta = cached
    img = image.convert("RGB")
    rounds = int(raz_rounds or 0) if raz is not None else 0
    res = predict_with_zoom(
        main, raz, img, dev, max_side=int(max_side or 1536),
        peak_threshold=float(conf_threshold if conf_threshold is not None
                             else 0.3),
        rounds=rounds, m=200, theta_z=0.01, kz=10, zoom_scale=2.0, seed=42)
    proc = res["image"]
    W, H = proc.size
    density = res["density"]
    pts = np.asarray(res["points"], dtype=np.float32)
    scores = np.asarray(res["scores"], dtype=np.float32)
    if pts.size == 0:
        pts = np.zeros((0, 2), dtype=np.float32)
        scores = np.zeros((0,), dtype=np.float32)
    fused, dcount, lcount = fuse_density_and_points(
        density, pts, scores, H, W, grid=4, theta_f=5.0)
    # Heatmap + red points, in the same shape as the other point models.
    d = F.interpolate(density.float(), size=(H, W), mode="bilinear",
                      align_corners=False)[0, 0].detach().cpu().numpy()
    d = d - d.min()
    if d.max() > 1e-8:
        d = d / d.max()
    import matplotlib.cm as cm
    heat = (cm.jet(d)[..., :3] * 255).astype(np.uint8)
    canvas = Image.blend(proc, Image.fromarray(heat), 0.45)
    draw = ImageDraw.Draw(canvas)
    radius = max(2, int(max(H, W) / 400))
    for x, y in pts[:5000]:
        draw.ellipse([x - radius, y - radius, x + radius, y + radius],
                     fill=(255, 0, 0))
    return {
        "count": round(float(fused), 2),
        "density_count": round(float(dcount), 2),
        "loc_count": int(lcount),
        "num_points": int(len(pts)),
        "points": [[round(float(x), 1), round(float(y), 1)]
                   for x, y in pts[:2000]],
        "scores": [round(float(s), 4) for s in scores[:2000]],
        "visualization": _to_b64(canvas),
        "density_map": _to_b64(Image.fromarray(heat)),
        "conf_threshold": float(conf_threshold),
        "raz_rounds": rounds,
        "model": "raz",
        "point_based": True,
    }
